values.content:
=You are a multilingual product copywriter. Generate compelling product descriptions in THREE languages.

Product Details:
- Name: {{ $json.body.product_name }}
- Category: {{ $json.body.category || 'General' }}
- Features: {{ $json.body.features }}
- Target Audience: {{ $json.body.target_audience || 'General consumers' }}
- Price Range: {{ $json.body.price_range || 'Not specified' }}

Generate for each language:
- Title (catchy, SEO-friendly)
- Short description (50 words)
- Long description (150 words)
- Key selling points (3-5 bullets)

Return JSON:
{
  "en": {"title": "", "short_desc": "", "long_desc": "", "selling_points": []},
  "id": {"title": "", "short_desc": "", "long_desc": "", "selling_points": []},
  "zh": {"title": "", "short_desc": "", "long_desc": "", "selling_points": []}
}

parameters.jsCode:
const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { en: { title: 'Error', short_desc: aiResponse }, id: { title: 'Error' }, zh: { title: 'Error' } };
}
const productName = items[0].json.body?.product_name || 'Unknown';
const formatLang = (lang) => {
  const d = parsed[lang] || {};
  return {
    title: d.title || '',
    shortDesc: d.short_desc || '',
    longDesc: d.long_desc || '',
    sellingPoints: Array.isArray(d.selling_points) ? d.selling_points.join(' | ') : ''
  };
};
return [{
  json: {
    productName,
    date: new Date().toISOString().split('T')[0],
    en_title: formatLang('en').title,
    en_short: formatLang('en').shortDesc,
    en_long: formatLang('en').longDesc,
    en_points: formatLang('en').sellingPoints,
    id_title: formatLang('id').title,
    id_short: formatLang('id').shortDesc,
    id_long: formatLang('id').longDesc,
    id_points: formatLang('id').sellingPoints,
    zh_title: formatLang('zh').title,
    zh_short: formatLang('zh').shortDesc,
    zh_long: formatLang('zh').longDesc,
    zh_points: formatLang('zh').sellingPoints
  }
}];
